--
-- Table structure for table `ton_kho`
--

DROP TABLE IF EXISTS `ton_kho`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ton_kho` (
  `maSP` int NOT NULL,
  `maKenh` int NOT NULL,
  `soLuongTon` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`maSP`,`maKenh`),
  KEY `maKenh` (`maKenh`),
  CONSTRAINT `ton_kho_ibfk_1` FOREIGN KEY (`maSP`) REFERENCES `san_pham` (`maSP`) ON DELETE CASCADE,
  CONSTRAINT `ton_kho_ibfk_2` FOREIGN KEY (`maKenh`) REFERENCES `kenh_ban_hang` (`maKenh`) ON DELETE CASCADE,
  CONSTRAINT `ton_kho_chk_1` CHECK ((`soLuongTon` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

